function updateCustomerSelect(categorySelector,customerSelector,reset=true){const category=document.querySelector(categorySelector).value,select=document.querySelector(customerSelector),old=reset?"":select.value,customers=sortRows(state.customers.filter((c)=>c.category===category),"code","asc");select.disabled=!category||!customers.length;select.innerHTML=!category?'<option>請先選擇客戶分類</option>':customers.length?'<option value="">請選擇客戶</option>'+customers.map((c)=>`<option value="${esc(c.id)}">${esc(c.code)}｜${esc(c.name)}</option>`).join(""):'<option>此分類目前沒有客戶</option>';if(old&&customers.some((c)=>c.id===old))select.value=old;}
function updateSiteCustomers(reset=true){updateCustomerSelect("#siteCustomerCategory","#siteCustomerSelector",reset);updateSiteContracts(reset);}
function updateSiteContracts(reset=true){const customerId=document.querySelector("#siteCustomerSelector").value,select=document.querySelector("#siteContractSelector"),old=reset?"":select.value,customer=byId(state.customers,customerId),services=customerContractServiceTypes(customer),legacySites=state.sites.filter((site)=>site.customerId===customerId&&!site.contractServiceTypeId);select.disabled=!customerId;let options=customerId?'<option value="">請選擇承攬內容</option>':'<option>請先選擇客戶</option>';if(services.length)options+=`<optgroup label="客戶承攬內容">${services.map((service)=>`<option value="contract:${esc(service.id)}">${esc(service.name)}</option>`).join("")}</optgroup>`;if(legacySites.length)options+=`<optgroup label="歷史未歸類（唯讀）">${legacySites.map((site)=>{const project=byId(state.projects,site.projectId);return `<option value="legacy:${esc(site.id)}">${esc(project?`${project.code}｜${project.name}`:site.siteName||site.siteCode||"既有案場")}</option>`;}).join("")}</optgroup>`;if(customerId&&!services.length&&!legacySites.length)options+='<option disabled>此客戶尚未設定承攬內容</option>';select.innerHTML=options;if([...select.options].some((option)=>option.value===old))select.value=old;renderSiteContractDetail();}
function selectedSiteContext(){const value=selectedSiteContractValue(),customer=byId(state.customers,document.querySelector("#siteCustomerSelector")?.value||"");if(!customer||!value)return null;if(value.startsWith("contract:")){const service=byId(state.contractServiceTypes,value.slice(9)),site=state.sites.find((row)=>row.customerId===customer.id&&row.contractServiceTypeId===service?.id);return service?{kind:"contract",customer,service,site,legacyProject:null,writable:true}:null;}if(value.startsWith("legacy:")){const site=byId(state.sites,value.slice(7)),legacyProject=byId(state.projects,site?.projectId);return site?{kind:"legacy",customer,service:null,site,legacyProject,writable:false}:null;}return null;}
