function renderAll(){renderSummary();renderInventory();renderTransactions();renderRepairs();renderMasterData();renderUsers();renderSystemLogs();renderWorkLogs();renderProjectReport();}
function currentPage(){return document.querySelector(".page.active")?.dataset.page||"dashboard";}
function requestedPageFromUrl(){const page=new URLSearchParams(location.search).get("page")||"";return Object.prototype.hasOwnProperty.call(PAGE_SCOPES,page)?page:"";}
function pageUrl(name){const target=new URL(location.href);target.searchParams.set("page",name);target.hash="";return `${target.pathname}${target.search}`;}
function preparePageLinks(){document.querySelectorAll(".nav-item[data-page]").forEach((link)=>{link.href=pageUrl(link.dataset.page);});}
function clearPageUrl(){const target=new URL(location.href);target.searchParams.delete("page");target.hash="";history.replaceState(null,"",`${target.pathname}${target.search}`);preparePageLinks();}
function setLoadState(message){document.querySelector("#syncState").innerHTML=`<i></i>${esc(message)}`;}
async function loadScope(scope,{force=false,silent=false}={}){
  if(!accessToken)return null;
  if(!force&&loadedScopes.has(scope))return lastSnapshot;
  if(scopeRequests.has(scope))return scopeRequests.get(scope);
  const request=(async()=>{
    setLoadState(`${pageMeta[currentPage()]?.[0]||"頁面"}資料載入中…`);
    try{
      const snapshot=await apiRequest({method:"GET",scope});
      hydrateSnapshot(snapshot);
      const errors=Array.isArray(snapshot.errors)?snapshot.errors:[];
      if(errors.length){loadedScopes.delete(scope);setLoadState(`部分資料載入失敗（${errors.length} 項）`);if(!silent)showToast(`${errors.length} 項資料暫時無法載入，可按重新整理重試。`,"部分資料未載入");}
      else{loadedScopes.add(scope);setLoadState(PREVIEW_MODE?"預覽資料已載入":"正式資料已載入");}
      return snapshot;
    }catch(error){setLoadState("資料載入失敗");if(error.status===401)logout({preservePage:true});else if(!silent)showToast(error.message,"載入失敗");throw error;}
    finally{scopeRequests.delete(scope);}
  })();
  scopeRequests.set(scope,request);return request;
}
async function loadPageData(page,{force=false,silent=false}={}){return loadScope(PAGE_SCOPES[page]||"dashboard",{force,silent});}
async function checkNasConnection(){
  if(!accessToken)return false;
  if(PREVIEW_MODE){nasConnectionState={checked:true,checking:false,available:false,message:"Preview 不使用正式 NAS 環境變數；附件只做瀏覽器安全模擬。"};renderSiteModules();return true;}
  nasConnectionState={checked:false,checking:true,available:false,message:"正在驗證 WebDAV、帳號與 /GUC-ERP 權限…"};
  renderSiteModules();
  try{
    const response=await fetch(NAS_API_ENDPOINT,{headers:{Authorization:`Bearer ${accessToken}`},cache:"no-store"}),data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data.error||"NAS 連線檢查失敗。");
    nasConnectionState={checked:true,checking:false,available:true,message:`${data.message}｜可寫入 ${data.root}`};
    return true;
  }catch(error){
    nasConnectionState={checked:true,checking:false,available:false,message:error.message};
    return false;
  }finally{
    renderSiteModules();
  }
}
async function switchPage(name){if(!Object.prototype.hasOwnProperty.call(PAGE_SCOPES,name))return;document.querySelectorAll(".page").forEach((p)=>p.classList.toggle("active",p.dataset.page===name));document.querySelectorAll(".nav-item").forEach((i)=>{const active=i.dataset.page===name;i.classList.toggle("active",active);if(active)i.setAttribute("aria-current","page");else i.removeAttribute("aria-current");});history.replaceState(null,"",pageUrl(name));preparePageLinks();document.querySelector("#pageTitle").textContent=pageMeta[name][0];document.querySelector("#pageSubtitle").textContent=pageMeta[name][1];document.querySelector("#sidebar").classList.remove("open");window.scrollTo({top:0,behavior:"smooth"});if(accessToken){await loadPageData(name);if(["sites","worklogs"].includes(name))await checkNasConnection();}}
function setupTabs(){document.querySelectorAll(".section-tabs").forEach((tabs)=>tabs.addEventListener("click",(event)=>{const button=event.target.closest("button[data-tab]");if(!button)return;const page=tabs.closest(".page");tabs.querySelectorAll("button").forEach((b)=>b.classList.toggle("active",b===button));page.querySelectorAll(":scope > .tab-pane").forEach((pane)=>pane.classList.toggle("active",pane.dataset.pane===button.dataset.tab));}));}

