function maintenanceEventCard(event={},customerId="",defaultWorkerIds=[]){const key=uid(),equipmentIds=event.equipmentIds||[],workerIds=event.workerIds?.length?event.workerIds:defaultWorkerIds,services=customerMaintenanceServices(customerId);return `<article class="maintenance-event-card" data-maintenance-event data-event-key="${esc(key)}" data-event-id="${esc(event.id||"")}" data-row-version="${esc(event.rowVersion||"")}" data-equipment-ids="${esc(JSON.stringify(equipmentIds))}"><header><div><span class="event-sequence">設備維修事件</span><b>內容沿用上方工作內容；可同時連結多台設備</b></div>${event.id?'<span>永久履歷｜錯誤時由管理員作廢</span>':'<button type="button" class="row-remove" data-remove-maintenance-event>移除</button>'}</header><div class="maintenance-event-grid">${selectField("eventType","事件類型",MAINTENANCE_EVENT_TYPES,event.eventType||"MAINTENANCE")}${selectField("eventServiceId","承攬內容",[["",services.length?"請選擇承攬內容":"請先選擇客戶"],...services.map((service)=>[service.id,service.name])],event.serviceId||"")}${inputField("eventOccurredAt","處理日期","date",true,event.occurredAt||today())}<label>設備<span class="equipment-picker-summary" data-equipment-summary>${esc(maintenanceEquipmentSummary(equipmentIds))}</span><button type="button" class="outline equipment-picker-button" data-open-equipment-picker>選擇設備</button></label>${inputField("eventResult","處理結果","textarea",true,event.result||"","span-2")}${inputField("eventCause","原因（選填）","textarea",false,event.cause||"")}${inputField("eventNotes","備註（選填）","textarea",false,event.notes||"")}</div>${maintenanceWorkerChecks(workerIds)}</article>`;}
function maintenanceEditorFields(log,customer,defaultWorkerIds=[]){const events=maintenanceEventsForLog(log.id||""),hasMaintenance=events.length>0;return `<label class="span-2 maintenance-question">本次是否有設備維修？<select name="hasMaintenance" ${hasMaintenance?"disabled":""}><option value="no" ${hasMaintenance?"":"selected"}>否，只有一般工作紀錄</option><option value="yes" ${hasMaintenance?"selected":""}>是，要建立設備履歷</option></select><small>${hasMaintenance?'此日誌已有永久設備履歷；可修改內容與連結，錯誤紀錄需由管理員作廢。':'選擇「是」後可建立多筆事件；同一事件可複選多台設備。'}</small></label><section id="maintenanceEditor" class="maintenance-editor span-2" ${hasMaintenance?"":"hidden"}><div class="maintenance-editor-head"><div><b>設備維修明細</b><small>「維修／設定內容」已與上方工作內容整合，以下只需填寫各事件的設備及處理結果。</small></div><button type="button" class="outline" data-add-maintenance-event>＋ 新增事件</button></div><div id="maintenanceEventList">${(events.length?events:[{}]).map((event)=>maintenanceEventCard(event,customer?.id||"",defaultWorkerIds)).join("")}</div></section><aside id="equipmentDrawer" class="equipment-drawer" aria-hidden="true"><div class="equipment-drawer-head"><div><small>依客戶與承攬內容篩選</small><b>選擇設備</b></div><button type="button" data-close-equipment-picker aria-label="關閉設備選擇">×</button></div><label class="equipment-drawer-search">搜尋設備<input type="search" data-equipment-search placeholder="名稱、編號、IP、位置或型號"></label><div class="equipment-drawer-list" data-equipment-options></div><div class="equipment-drawer-foot"><span data-equipment-count>已選 0 台</span><button type="button" class="primary" data-close-equipment-picker>完成選擇</button></div></aside>`;}
