function refreshMaintenanceServices(reset=false){const form=document.querySelector("#modalForm"),services=customerMaintenanceServices(workLogFormCustomerId());form.querySelectorAll('[data-maintenance-event] select[name="eventServiceId"]').forEach((select)=>{const current=reset?"":select.value;select.innerHTML=`<option value="">${services.length?"請選擇承攬內容":"此客戶尚未設定承攬內容"}</option>`+services.map((service)=>`<option value="${esc(service.id)}">${esc(service.name)}</option>`).join("");if(services.some((service)=>service.id===current))select.value=current;else{select.closest("[data-maintenance-event]").dataset.equipmentIds="[]";syncMaintenanceEquipmentSummary(select.closest("[data-maintenance-event]"));}});}
