function renderEquipmentDrawer(){const drawer=document.querySelector("#equipmentDrawer"),form=document.querySelector("#modalForm");if(!drawer||drawer.getAttribute("aria-hidden")==="true")return;const card=form.querySelector(`[data-event-key="${CSS.escape(drawer.dataset.eventKey||"")}"]`);if(!card)return;const customerId=workLogFormCustomerId(),serviceId=card.querySelector('[name="eventServiceId"]')?.value||"",search=String(drawer.querySelector("[data-equipment-search]")?.value||"").trim().toLocaleLowerCase("zh-Hant");let selected=[];try{selected=JSON.parse(card.dataset.equipmentIds||"[]");}catch{}const selectedIds=new Set(selected),rows=state.equipmentRegistry.filter((row)=>row.customerId===customerId&&row.serviceId===serviceId&&row.status==="active"&&(!search||[row.displayName,row.searchKey,equipmentTypeLabel(row.equipmentType)].some((value)=>valueText(value).includes(search))));drawer.querySelector("[data-equipment-options]").innerHTML=!serviceId?'<div class="drawer-empty">請先選擇承攬內容。</div>':rows.length?rows.map((row)=>`<label><input type="checkbox" data-equipment-choice value="${esc(row.id)}" ${selectedIds.has(row.id)?"checked":""}><span><b>${esc(row.displayName)}</b><small>${esc(equipmentTypeLabel(row.equipmentType))}${row.metadata?.ip_address?`｜${esc(row.metadata.ip_address)}`:""}</small></span></label>`).join(""):'<div class="drawer-empty"><b>設備未建檔</b><br>此承攬內容沒有符合條件的正式設備，請先至案場系統完成設備建檔。</div>';drawer.querySelector("[data-equipment-count]").textContent=`已選 ${selected.length} 台`;}
function openEquipmentDrawer(card){const serviceId=card.querySelector('[name="eventServiceId"]')?.value||"";if(!serviceId)return showToast("請先選擇承攬內容，再選擇設備。","尚未選擇承攬內容");const drawer=document.querySelector("#equipmentDrawer");drawer.dataset.eventKey=card.dataset.eventKey;drawer.setAttribute("aria-hidden","false");drawer.querySelector("[data-equipment-search]").value="";renderEquipmentDrawer();drawer.querySelector("[data-equipment-search]").focus();}
function closeEquipmentDrawer(){const drawer=document.querySelector("#equipmentDrawer");if(!drawer)return;drawer.setAttribute("aria-hidden","true");drawer.dataset.eventKey="";}
function collectMaintenanceEvents(){const form=document.querySelector("#modalForm");if(form.elements.hasMaintenance?.value!=="yes")return[];const sharedDescription=form.elements.summary?.value.trim()||"";if(!sharedDescription)throw new Error("有設備維修時，請填寫「工作內容／維修設定內容」。");const cards=[...form.querySelectorAll("[data-maintenance-event]")];if(!cards.length||cards.length>20)throw new Error("設備維修事件必須為 1～20 筆。");return cards.map((card,index)=>{let equipmentIds=[];try{equipmentIds=JSON.parse(card.dataset.equipmentIds||"[]");}catch{}const eventType=card.querySelector('[name="eventType"]').value,serviceId=card.querySelector('[name="eventServiceId"]').value,occurredAt=card.querySelector('[name="eventOccurredAt"]').value,description=sharedDescription,result=card.querySelector('[name="eventResult"]').value.trim(),cause=card.querySelector('[name="eventCause"]').value.trim(),notes=card.querySelector('[name="eventNotes"]').value.trim(),workerIds=[...card.querySelectorAll("[data-event-worker]:checked")].map((input)=>input.value);if(!serviceId)throw new Error(`第 ${index+1} 筆維修事件：請選擇承攬內容。`);if(!occurredAt||!result)throw new Error(`第 ${index+1} 筆維修事件：請完整填寫日期與處理結果。`);if(!equipmentIds.length)throw new Error(`第 ${index+1} 筆維修事件：至少選擇一台設備。`);return{id:card.dataset.eventId||null,row_version:card.dataset.eventId?Number(card.dataset.rowVersion):null,event_type:eventType,service_id:serviceId,occurred_at:occurredAt,description,result,cause,notes,equipment_ids:equipmentIds,worker_user_ids:workerIds};});}
function projectOwnerPickerField(selected=[]){return workerPickerField(selected,{legend:"負責人",name:"projectWorkerIds",description:"可複選既有系統使用者；新增工作日誌選到此專案時會自動帶入施工人員。"});}
function contractServicePickerField(selected=[]){const selectedCodes=new Set(selected);return `<fieldset class="worker-picker contract-service-picker span-2"><legend>承攬內容</legend><p>可複選；選項由系統資料表管理，未來可直接擴充。</p><div>${state.contractServiceTypes.filter((service)=>service.active).sort((a,b)=>a.sortOrder-b.sortOrder).map((service)=>`<label><input type="checkbox" name="contractServiceCodes" value="${esc(service.code)}" ${selectedCodes.has(service.code)?"checked":""}><span>${esc(service.name)}</span></label>`).join("")}</div></fieldset>`;}
function workLogProjectTitleField(customerId,value="",readonly=false){const options=state.projects.filter((project)=>project.customerId===customerId).map((project)=>`<option value="${esc(project.name)}">${esc(project.code)}</option>`).join("");return `<label class="span-2">專案／日誌標題<input name="projectName" value="${esc(value)}" list="workLogProjectNames" maxlength="120" required ${readonly?'readonly aria-readonly="true"':""}><datalist id="workLogProjectNames">${options}</datalist><small>${readonly?"既有日誌鎖定原專案，避免附件與取貨關聯被移動。":"可選既有專案名稱；輸入新標題時，儲存後會自動建立該客戶的專案並建立關聯。"}</small></label>`;}
function workLogTimePeriodField(value=""){return `<label>時段<input name="timePeriod" type="text" value="${esc(value)}" maxlength="80" placeholder="例如：08:30–12:00 或 上午"><small>可填實際施工時段，最多 80 個字。</small></label>`;}
function submitField(text){return`<div class="form-submit"><button class="primary" type="submit">${esc(text)}</button></div>`;}
function customerCategoryOptions(value=""){return selectField("customerCategory","客戶分類",[["","請選擇分類"],...CUSTOMER_CATEGORIES],value);}
function customerOptions(value="",category=""){return selectField("customerId","客戶",[["",category?"請選擇客戶":"請先選擇客戶分類"],...sortRows(state.customers.filter((c)=>category&&c.category===category),"code","asc").map((c)=>[c.id,`${c.code}｜${c.name}`])],value);}
function projectOptions(customerId,value=""){return selectField("projectId","專案",[["","請選擇專案"],...state.projects.filter((p)=>p.customerId===customerId&&p.status!=="completed").map((p)=>[p.id,`${p.code}｜${p.name}`])],value);}
