function repairInventoryFields(itemId=""){const item=byId(state.inventory,itemId),categoryId=item?.categoryId||"";return selectField("itemCategory","商品種類",[["","請選擇種類"],...state.categories.filter((category)=>category.active).map((category)=>[category.id,category.name])],categoryId)+selectField("itemId","商品",[["",categoryId?"請選擇商品":"請先選擇商品種類"],...state.inventory.filter((row)=>row.categoryId===categoryId).map((row)=>[row.id,`${row.code}｜${row.name}｜${row.brand} ${row.model}`])],itemId);}

function itemCategoryOptions(value=""){return '<option value="">請選擇種類</option>'+state.categories.filter((c)=>c.active).map((c)=>`<option value="${esc(c.id)}" ${c.id===value?"selected":""}>${esc(c.name)}</option>`).join("");}
function inventoryItemOptions(categoryId,value=""){return '<option value="">請選擇品項</option>'+state.inventory.filter((i)=>i.categoryId===categoryId).map((i)=>`<option value="${esc(i.id)}" ${i.id===value?"selected":""}>${esc(i.code)}｜${esc(i.name)}｜${esc(i.brand)} ${esc(i.model)}</option>`).join("");}
function transactionBatchRow(type,row={}){const note=type==="receipt"?'<label>備註<input name="batchNote" value="'+esc(row.note||"")+'" placeholder="選填"></label>':"";return `<div class="batch-row transaction-batch-row" data-batch-row><span class="batch-sequence" aria-label="序號"></span><label>貨品種類<select name="batchCategory" data-batch-category required>${itemCategoryOptions(row.categoryId||"")}</select></label><label>品項<select name="batchItem" data-batch-item required ${row.categoryId?"":"disabled"}>${inventoryItemOptions(row.categoryId||"",row.itemId||"")}</select></label><label>數量<input name="batchQuantity" type="number" min="1" step="1" value="${esc(row.quantity||1)}" required></label>${note}<button class="row-remove" type="button" data-remove-batch-row aria-label="刪除此列">刪除</button></div>`;}
function itemBatchRow(row={}){return `<div class="batch-row item-batch-row" data-item-batch-row><label data-mobile-label="貨品種類"><select name="category" required>${itemCategoryOptions(row.categoryId||"")}</select></label><label data-mobile-label="品項名稱"><input name="name" value="${esc(row.name||"")}" required></label><label data-mobile-label="品牌"><input name="brand" value="${esc(row.brand||"")}" required></label><label data-mobile-label="型號"><input name="model" value="${esc(row.model||"")}"></label><label data-mobile-label="單位"><input name="unit" value="${esc(row.unit||"台")}" required></label><label data-mobile-label="期初庫存"><input name="quantity" type="number" min="0" step="1" value="${esc(row.quantity??0)}" required></label><button class="row-remove" type="button" data-remove-item-row aria-label="刪除此列">刪除</button></div>`;}
function updateBatchButtons(){const transaction=document.querySelector("#transactionBatchRows"),transactionButton=document.querySelector("[data-add-transaction-row]");if(transactionButton)transactionButton.disabled=(transaction?.children.length||0)>=MAX_BATCH_ROWS;const items=document.querySelector("#itemBatchRows"),itemButton=document.querySelector("[data-add-item-row]");if(itemButton)itemButton.disabled=!canAdmin()||(items?.children.length||0)>=MAX_BATCH_ROWS;}
function addTransactionBatchRow(type,row={}){const container=document.querySelector("#transactionBatchRows");if(!container||container.children.length>=MAX_BATCH_ROWS)return showToast(`每批最多 ${MAX_BATCH_ROWS} 筆。`,"已達上限");container.insertAdjacentHTML("beforeend",transactionBatchRow(type,row));updateBatchButtons();}
function addItemBatchRow(row={}){const container=document.querySelector("#itemBatchRows");if(!container||container.children.length>=MAX_BATCH_ROWS)return showToast(`每批最多 ${MAX_BATCH_ROWS} 筆。`,"已達上限");container.insertAdjacentHTML("beforeend",itemBatchRow(row));updateBatchButtons();}
