async function mutate(operation,payload,message){if(PREVIEW_MODE){const result=applyPreviewMutation(operation,payload);if(message)showToast(`${message}（僅預覽暫存）`);return result;}const result=await apiRequest({operation,payload});loadedScopes.clear();await loadPageData(currentPage(),{force:true});if(message)showToast(message);return result;}

function setAttachmentUploadProgress(stage,message){const progress=document.querySelector("#attachmentUploadProgress");if(!progress)return;progress.hidden=false;progress.dataset.stage=stage;progress.textContent=message;progress.scrollIntoView?.({behavior:"smooth",block:"nearest"});}
async function nasFormRequest(body,timeout=120_000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);try{const response=await fetch(NAS_API_ENDPOINT,{method:"POST",headers:{Authorization:`Bearer ${accessToken}`},body,signal:controller.signal}),result=await response.json().catch(()=>({}));if(!response.ok)throw new Error(result.error||"附件無法上傳至 NAS。");return result;}catch(error){if(error.name==="AbortError")throw new Error("附件上傳逾時，請縮小檔案後再試。");throw error;}finally{clearTimeout(timer);}}
