function renderProjectReport(){
  const container=document.querySelector("#materialSummary");
  if(!container)return;
  const errors=reportErrorDatasets();
  if(errors.length){container.innerHTML=reportEmpty("報表資料載入不完整",`缺少 ${errors.map((error)=>error.dataset).join("、")}，請重新整理後再試。`,"!");return;}
  const {project,report}=selectedProjectReport();
  if(!project){container.innerHTML=reportEmpty("請選擇客戶與專案","系統只會顯示該客戶實際關聯的專案。");return;}
  if(!report){container.innerHTML=reportEmpty("報表模組尚未就緒","請重新整理頁面後再試。","!");return;}
  if(report.error){container.innerHTML=reportEmpty("日期區間不正確",report.error,"!");return;}
  document.querySelectorAll("[data-report-tab]").forEach((button)=>{const active=button.dataset.reportTab===activeProjectReportTab;button.classList.toggle("active",active);button.setAttribute("aria-selected",String(active));});
  const heading=`<article class="panel report-heading"><div><span class="pill">${esc(project.code||"未編號")}</span><h2>${esc(project.name)}</h2><p>${esc(project.type||"工程施工")}｜${project.status==="completed"?"已完成":"進行中"}</p></div>${statusLabel(project.status)}</article>`;
  const content=activeProjectReportTab==="materials"?renderProjectMaterials(report):activeProjectReportTab==="workers"?renderProjectWorkers(project,report):renderProjectOverview(project,report);
  container.innerHTML=heading+content;
}
function exportProjectMaterials(){
  const errors=reportErrorDatasets();
  if(errors.length)return showToast("報表資料載入不完整，請重新整理後再匯出。","無法匯出");
  const {project,report}=selectedProjectReport();
  if(!project||!report)return showToast("請先選擇專案，再匯出用料清單。","提示");
  if(report.error)return showToast(report.error,"無法匯出");
  const rows=["日期,品項,品牌,型號,數量,單位,取貨帳號",...report.materialRows.map((row)=>[row.date,row.item?.name||"未知品項",row.item?.brand||"",row.item?.model||"",row.quantity,row.item?.unit||"",row.account||""].map(csvCell).join(","))];
  download(`project-materials-${project.code||project.id}-${today()}.csv`,"\ufeff"+rows.join("\n"),"text/csv;charset=utf-8");
  showToast(`已匯出 ${report.materialRows.length} 筆篩選後用料明細。`);
}
function download(name,content,type="application/json"){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
