function showLogin(message=""){document.querySelector("#loginGate").classList.add("open");const error=document.querySelector("#loginError");error.textContent=message;error.classList.toggle("show",!!message);}
function hideLogin(){document.querySelector("#loginGate").classList.remove("open");document.querySelector("#loginError").classList.remove("show");}
async function loadQuotationAccess(){const requestToken=accessToken;state.quotationAccess=false;if(!requestToken){applyUserState();return false;}const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),4000);let allowed=false;try{const response=await fetch(`${QUOTATION_API_ENDPOINT}?entity=session`,{headers:{Authorization:`Bearer ${requestToken}`},cache:"no-store",signal:controller.signal});const data=await response.json().catch(()=>({}));allowed=response.ok&&data.current_user?.can_access_quotations===true;}catch{allowed=false;}finally{clearTimeout(timer);}if(requestToken!==accessToken)return false;state.quotationAccess=allowed;applyUserState();return allowed;}
function showSystemChooser(){const chooser=document.querySelector("#systemChooser"),status=document.querySelector("#systemChooserStatus");chooser.classList.add("open");chooser.setAttribute("aria-hidden","false");if(status){const available=[];if(SITE_SYSTEM_TARGET_URL)available.push("案場資料");if(QUOTATION_SYSTEM_TARGET_URL)available.push("報價管理");status.textContent=available.length?`${available.join("、")}系統已可選擇；選定後才會載入該系統資料。`:"外部工作系統網址尚未設定；本次不會建立假網址或錯誤跳轉。";}}
function showSystemChooserAfterAuthentication(){state.quotationAccess=false;applyUserState();showSystemChooser();}
function hideSystemChooser(){const chooser=document.querySelector("#systemChooser");chooser.classList.remove("open");chooser.setAttribute("aria-hidden","true");}
async function continueAfterAuthentication(){const requestedPage=requestedPageFromUrl();if(!requestedPage){showSystemChooserAfterAuthentication();return;}state.quotationAccess=false;applyUserState();hideSystemChooser();await switchPage(requestedPage);}
function openExternalSystem({url,origin,readyMessage,sessionMessage,label,externalWindow=null}){
  if(!url||!origin){showToast(`尚未設定${label}網址，因此未開啟新分頁。`,`${label}尚未開放`);return false;}
  if(!accessToken){showLogin(`請先登入 ERP，再開啟${label}。`);return false;}
  const nonce=crypto.randomUUID(),target=new URL(url);
  target.searchParams.set("sso","erp");target.searchParams.set("sso_nonce",nonce);
  let timer=0;
  const receiveReady=(event)=>{
    const message=event.data;
    if(event.origin!==origin||event.source!==externalWindow||!message||typeof message!=="object"||message.type!==readyMessage||message.nonce!==nonce)return;
    if(!accessToken)return;
    externalWindow.postMessage({type:sessionMessage,nonce,accessToken},origin);
    window.removeEventListener("message",receiveReady);clearTimeout(timer);
  };
  window.addEventListener("message",receiveReady);
  if(externalWindow)externalWindow.location.replace(target.toString());else externalWindow=window.open(target.toString(),"_blank");
  if(!externalWindow){window.removeEventListener("message",receiveReady);showToast("瀏覽器已阻擋新分頁，請允許此網站開啟彈出式視窗。",`無法開啟${label}`);return false;}
  timer=setTimeout(()=>window.removeEventListener("message",receiveReady),15000);
  return true;
}
function openSiteSystem(){return openExternalSystem({url:SITE_SYSTEM_TARGET_URL,origin:SITE_SYSTEM_TARGET_ORIGIN,readyMessage:SITE_SSO_READY_MESSAGE,sessionMessage:SITE_SSO_SESSION_MESSAGE,label:"案場資料系統"});}
function openQuotationSystem(externalWindow=null){if(!canAccessQuotations()){showToast("此帳號未列入報價管理系統白名單。","沒有報價權限");return false;}return openExternalSystem({url:QUOTATION_SYSTEM_TARGET_URL,origin:QUOTATION_SYSTEM_TARGET_ORIGIN,readyMessage:QUOTATION_SSO_READY_MESSAGE,sessionMessage:QUOTATION_SSO_SESSION_MESSAGE,label:"報價管理系統",externalWindow});}
async function chooseSystem(target,button){
  const status=document.querySelector("#systemChooserStatus");
  if(target==="sites"){
    const opened=openSiteSystem();
    if(!opened){if(status)status.textContent="案場資料新分頁未能開啟，請確認網址與瀏覽器設定。";return;}
    hideSystemChooser();
    return;
  }
  if(target==="quotations"){
    if(!QUOTATION_SYSTEM_TARGET_URL||!QUOTATION_SYSTEM_TARGET_ORIGIN){if(status)status.textContent="報價管理網址尚未設定。";return;}
    const pendingWindow=window.open("","_blank");
    if(!pendingWindow){if(status)status.textContent="瀏覽器已阻擋新分頁，請允許此網站開啟彈出式視窗。";return;}
    button.disabled=true;
    const hint=button.querySelector("small"),originalHint=hint.textContent;
    hint.textContent="正在確認報價權限…";
    try{
      if(!await loadQuotationAccess()){pendingWindow.close();if(status)status.textContent="此帳號沒有報價管理系統權限。";return;}
      const opened=openQuotationSystem(pendingWindow);
      if(!opened){pendingWindow.close();if(status)status.textContent="報價管理新分頁未能開啟，請確認權限與網址。";return;}
      hideSystemChooser();
    }finally{button.disabled=false;hint.textContent=originalHint;}
    return;
  }
  if(target!=="erp")return;
  button.disabled=true;button.querySelector("small").textContent="正在載入 Dashboard…";
  try{hideSystemChooser();await switchPage("dashboard");}
  catch(error){showSystemChooser();showToast(error.message,"ERP 首頁載入失敗");}
  finally{button.disabled=false;button.querySelector("small").textContent="進入目前的專案與庫存 Dashboard";}
}
