document.querySelector("#adjustForm").addEventListener("submit",async(event)=>{event.preventDefault();const form=event.currentTarget,d=Object.fromEntries(new FormData(form)),afterQuantity=Number(d.quantity),selectedItem=byId(state.inventory,d.item);form.classList.add("busy");try{if(!selectedItem||selectedItem.categoryId!==d.category)throw new Error("所選品項不屬於該貨品種類，請重新選擇。");if(!Number.isInteger(afterQuantity)||afterQuantity<0)throw new Error("校正後數量須為 0 以上整數。");const response=await mutate("create_stock_adjustment",{inventory_item_id:d.item,after_quantity:afterQuantity,reason:d.reason||"",idempotency_key:uid()},"");const verification=PREVIEW_MODE?response:Array.isArray(response?.result)?response.result[0]:response?.result;if(Number(verification?.verified_quantity)!==afterQuantity)throw new Error("資料庫未能確認校正後數量，請重新整理並再次核對。");let actualQuantity=Number(byId(state.inventory,d.item)?.quantity);if(actualQuantity!==afterQuantity&&!PREVIEW_MODE){await loadPageData("inventory",{force:true});actualQuantity=Number(byId(state.inventory,d.item)?.quantity);}if(actualQuantity!==afterQuantity)throw new Error(`即時庫存核對不一致（預期 ${afterQuantity}，目前 ${Number.isFinite(actualQuantity)?actualQuantity:"無資料"}），請勿重複校正並通知管理者。`);showToast(`${selectedItem.code} 已校正為 ${afterQuantity} ${selectedItem.unit}`,"庫存已校正並核對");form.reset();renderInventory();}catch(error){showToast(error.message,"校正失敗");}finally{form.classList.remove("busy");}});

